document.addEventListener('visibilitychange',()=>{const contexts=[audio.context,...[...audio.children].map(c=>c.context)].filter(Boolean);if(document.hidden){if(page==='play'&&adapter.api&&playStarted&&!playReady&&!loading&&!$('desk-dialog').open){try{const g=adapter.api.get();if(!g.paused&&g.mode==='play')adapter.api.pause()}catch{}}for(const c of contexts)try{c.suspend()}catch{}}else for(const c of contexts)try{c.resume()}catch{}});
