const veil=!!(selected&&page==='play'&&adapter.api&&(playReady||$('desk-dialog').open&&$('desk-dialog').dataset.screen==='pause'));{const v=globalThis.No2Tracing?.variant?.()||'';if((document.body.dataset.tracing||'')!==v){if(v)document.body.dataset.tracing=v;else delete document.body.dataset.tracing}}if(veil!==tracingOn){tracingOn=veil;globalThis.No2Tracing?.setShell(veil)}// The masking tape shows with any tracing sheet, the shell's or the game's own (gameSeen).
